INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template) VALUES
  (41, 1, 'Pod 가 무엇인지 알기', '쿠버네티스에서 애플리케이션을 실행하는 가장 작은 배포 단위는 무엇일까요?', '컨테이너를 직접 다루지 않고, 컨테이너를 감싸는 단위를 만듭니다.', NULL, NULL, '[]', 'choice', '["컨테이너 한 개를 반드시 하나만 담는 상자이다", "컨테이너를 하나 이상 담는 가장 작은 배포 단위인 Pod 이다", "여러 대의 서버를 묶은 클러스터이다", "이미지를 저장하는 저장소이다"]', 1, '**Pod** 는 쿠버네티스가 다루는 가장 작은 배포 단위입니다. 보통 컨테이너 하나를 담지만, 함께 움직여야 하는 컨테이너를 여러 개 담을 수도 있고, 같은 Pod 안의 컨테이너는 네트워크(localhost)와 저장소를 나눠 씁니다.', NULL, NULL),
  (41, 2, 'Deployment 가 하는 일 알기', 'Pod 를 직접 만들지 않고 **Deployment** 로 만드는 이유로 알맞은 것은 무엇일까요?', 'Pod 가 죽으면 누가 다시 만들어 줄까요? 개수를 늘리거나 새 버전으로 바꿀 때는요?', NULL, NULL, '[]', 'choice', '["Deployment 가 있어야만 Pod 가 시작된다", "원하는 Pod 개수를 유지하고(죽으면 다시 만든다), 롤링 업데이트와 롤백을 해 준다", "Deployment 는 Pod 보다 항상 빠르다", "Deployment 는 네트워크 접속 주소를 만든다"]', 1, 'Deployment 는 "이 Pod 를 3개 유지해라"를 선언해 두면 개수를 맞춰 주고(죽으면 새로 만들고), 새 버전으로 천천히 바꾸는 롤링 업데이트와 되돌리는 롤백도 해 줍니다. 네트워크 주소는 Service 가 담당합니다.', NULL, NULL),
  (41, 3, '앱을 배포하고 늘리고 노출하는 kubectl 순서대로 놓기', 'nginx 앱을 배포하고 Pod 를 늘리고 Service 로 노출하는 명령이 섞여 있습니다. **자연스러운 작업 순서**대로 놓으세요.', '먼저 배포하고 확인한 뒤, 개수를 늘리고, 마지막에 접속할 수 있게 Service 를 만들어 확인합니다.', NULL, NULL, '[]', 'order', '["`kubectl expose deployment web --port=80` 로 Service 만들기", "`kubectl scale deployment web --replicas=3` 로 3개로 늘리기", "`kubectl get pods` 로 Pod 확인", "`kubectl create deployment web --image=nginx` 로 앱 배포", "`kubectl get svc` 로 Service 확인"]', NULL, '`create deployment`(배포) → `get pods`(확인) → `scale`(개수 늘리기) → `expose`(Service 로 노출) → `get svc`(확인) 순서입니다. Service 는 Pod 가 늘거나 바뀌어도 변하지 않는 접속 주소를 줍니다.', '[3, 2, 1, 0, 4]', NULL),
  (41, 4, 'kubectl scale 명령의 빈칸 채우기', 'Deployment `web` 의 Pod 개수를 **3개**로 바꾸려고 합니다. 명령의 빈칸을 채우세요.', '개수를 바꾸는 하위 명령 하나와, `--replicas=` 뒤에 올 숫자가 필요합니다.', NULL, NULL, '[]', 'fill', '["scale", "get", "describe", "3", "80"]', NULL, '`kubectl scale` 은 Deployment 의 복제본(replicas) 개수를 바꿉니다. `get` 은 목록 조회, `describe` 는 자세한 정보 보기입니다. `80` 은 포트 번호처럼 보이지만 개수와는 관계없습니다.', '[0, 3]', 'kubectl {0} deployment web --replicas={1}'),
  (41, 5, 'Service 가 필요한 이유 알기', 'Pod 는 죽었다 다시 만들어질 때마다 **IP 주소가 바뀝니다.** 그런데도 다른 앱이 항상 같은 주소로 접속할 수 있게 해 주는 것은 무엇일까요?', '바뀌지 않는 이름과 주소를 주고, 뒤의 여러 Pod 로 요청을 나눠 줍니다.', NULL, NULL, '[]', 'choice', '["ConfigMap", "Namespace", "Service (고정된 접속 주소를 주고 뒤의 Pod 들로 요청을 나눠 준다)", "Node"]', 2, '**Service** 는 라벨로 고른 Pod 들 앞에 고정된 가상 IP 와 이름을 붙이고, 요청을 그 Pod 들로 나눠 줍니다. Pod 의 IP 가 바뀌어도 Service 주소는 그대로라서 안정적으로 접속할 수 있습니다.', NULL, NULL),
  (41, 6, 'Namespace 의 역할 알기', '하나의 클러스터에서 팀이나 환경(예: dev, prod)별로 리소스를 나눠서 쓰고 싶습니다. 어떤 것을 쓰면 될까요?', '같은 이름의 리소스를 서로 다른 구역에 만들 수 있어야 합니다.', NULL, NULL, '[]', 'choice', '["Pod", "Namespace (클러스터 안의 리소스를 이름으로 나누는 구역)", "Deployment", "Secret"]', 1, '**Namespace** 는 한 클러스터 안에서 리소스를 논리적으로 나누는 구역입니다. 같은 이름의 리소스도 Namespace 가 다르면 따로 존재할 수 있고, 권한이나 자원 제한을 구역별로 줄 수도 있습니다.', NULL, NULL),
  (41, 7, 'ConfigMap 과 Secret 구분하기', '앱에 넘길 값 두 가지가 있습니다. (가) 로그 레벨 `INFO`, (나) 데이터베이스 비밀번호. 쿠버네티스에서 각각 무엇에 담는 것이 알맞을까요?', '일반 설정과 민감한 값은 따로 다룹니다.', NULL, NULL, '[]', 'choice', '["(가) Secret, (나) ConfigMap", "(가) ConfigMap, (나) Secret", "둘 다 ConfigMap", "둘 다 Namespace"]', 1, '일반 설정 값은 **ConfigMap**, 비밀번호나 토큰 같은 민감한 값은 **Secret** 에 담습니다. Secret 은 기본적으로 base64 로 인코딩될 뿐 암호화는 아니라서, 접근 권한을 제한하고 필요하면 암호화 설정을 함께 써야 합니다.', NULL, NULL),
  (41, 8, 'CrashLoopBackOff 상태 읽기', '`kubectl get pods` 에서 어떤 Pod 의 상태가 `CrashLoopBackOff` 로 보입니다. 무슨 뜻일까요?', '컨테이너가 시작되자마자 죽고, 쿠버네티스가 다시 시작하기를 반복하는 상태입니다.', NULL, NULL, '[]', 'choice', '["이미지를 내려받는 중이다", "컨테이너가 시작한 뒤 계속 죽어서 재시작을 반복하고 있다", "노드에 자리가 없어 아직 배치되지 않았다", "정상적으로 종료되었다"]', 1, '`CrashLoopBackOff` 는 컨테이너가 시작 직후 계속 종료되어 쿠버네티스가 재시작을 반복하는 상태입니다(재시작 간격이 점점 길어집니다). 원인은 `kubectl logs` 와 `kubectl describe` 로 찾습니다. 이미지를 받는 중은 `ContainerCreating`/`ImagePullBackOff`, 자리가 없으면 `Pending` 입니다.', NULL, NULL);
